"""Waveshare ESP32-P4-ETH thermocouple, MQTT publisher and configuration UI."""

import asyncio
import binascii
import machine
import network
import time

from config_web import ConfigServer, load_config, temperature_json
from max31855 import MAX31855

try:
    from umqtt.simple import MQTTClient
except ImportError:
    MQTTClient = None

SENSOR_SCK = 18
SENSOR_MISO = 19
SENSOR_MOSI = 16
SENSOR_CS = 17
MQTT_RETRY_MS = 30000


def setup_lan(config):
    """Configure IPv4 before starting Ethernet to avoid competing DHCP starts."""
    if not hasattr(network, "LAN") or not hasattr(network, "PHY_IP101"):
        raise RuntimeError("Diese Firmware benoetigt ESP32-P4 network.LAN mit IP101-Unterstuetzung.")
    lan = network.LAN(
        mdc=machine.Pin(31), mdio=machine.Pin(52), reset=machine.Pin(51),
        phy_type=network.PHY_IP101, phy_addr=1,
        ref_clk=machine.Pin(50), ref_clk_mode=machine.Pin.IN,
    )
    print("Ethernet: IP-Konfiguration vor LAN-Aktivierung.")
    lan.active(False)
    if config["dhcp"]:
        lan.ipconfig(dhcp4=True)
    else:
        lan.ifconfig(tuple(config[name] for name in ("ip", "netmask", "gateway", "dns")))
    lan.active(True)
    return lan


class Device:
    """Keep sensor sampling, bounded MQTT attempts and reboot state together."""

    def __init__(self, config, lan, sensor):
        """Store hardware handles without connecting to the broker at startup."""
        self.config = config
        self.lan = lan
        self.sensor = sensor
        self.temperature = None
        self.sensor_status = "Noch keine Messung"
        self.client = None
        self.mqtt_status = "deaktiviert"
        if config["mqtt_server"]:
            self.mqtt_status = "getrennt" if MQTTClient else "umqtt.simple fehlt"
        self.last_sample = time.ticks_add(time.ticks_ms(), -1000)
        self.last_publish = time.ticks_ms()
        self.last_connect = time.ticks_add(time.ticks_ms(), -MQTT_RETRY_MS)
        self.reboot_at = None

    def status(self):
        """Return only public runtime data, never broker credentials."""
        return {"ip": self.lan.ifconfig()[0], "temperature": self.temperature,
                "sensor": self.sensor_status, "mqtt": self.mqtt_status}

    def request_restart(self):
        """Allow the save response to finish before resetting the device."""
        self.reboot_at = time.ticks_add(time.ticks_ms(), 3000)

    def close_mqtt(self):
        """Release the broker socket even after a failed connection or write."""
        if self.client is not None:
            if self.client.sock is not None:
                try:
                    self.client.sock.close()
                except OSError:
                    pass
            self.client = None

    def connect_mqtt(self):
        """Use a unique client ID and bounded socket I/O; keepalive is disabled."""
        self.last_connect = time.ticks_ms()
        self.client = MQTTClient(
            b"esp32-p4-" + binascii.hexlify(machine.unique_id()),
            self.config["mqtt_server"], port=self.config["mqtt_port"],
            user=self.config["mqtt_user"].encode() or None,
            password=self.config["mqtt_password"].encode(), keepalive=0,
        )
        try:
            self.client.connect(timeout=2)
            self.client.sock.settimeout(2)
            self.mqtt_status = "verbunden"
            print("MQTT verbunden.")
        except Exception as error:
            self.close_mqtt()
            self.mqtt_status = "Verbindungsfehler"
            if isinstance(error, TypeError):
                self.mqtt_status = "umqtt.simple aktualisieren (timeout fehlt)"
            print("MQTT:", self.mqtt_status)

    def step(self):
        """Sample once per second and publish/reconnect on wrap-safe deadlines."""
        now = time.ticks_ms()
        if self.reboot_at is not None:
            if time.ticks_diff(now, self.reboot_at) >= 0:
                self.close_mqtt()
                machine.reset()
            return
        if time.ticks_diff(now, self.last_sample) >= 1000:
            try:
                if self.sensor:
                    self.temperature, self.sensor_status = self.sensor.read()
                else:
                    self.temperature, self.sensor_status = None, "SPI nicht initialisiert"
            except OSError:
                self.temperature, self.sensor_status = None, "SPI-Fehler"
            self.last_sample = now
        if not self.lan.isconnected():
            self.close_mqtt()
            if self.config["mqtt_server"]:
                self.mqtt_status = "Ethernet getrennt"
            return
        if not MQTTClient or not self.config["mqtt_server"]:
            return
        if self.client is None and time.ticks_diff(now, self.last_connect) >= MQTT_RETRY_MS:
            self.connect_mqtt()
        if time.ticks_diff(now, self.last_publish) >= self.config["interval"] * 1000:
            if self.client is not None and self.temperature is not None:
                try:
                    self.client.publish(self.config["mqtt_topic"].encode(),
                                        temperature_json(self.temperature, self.sensor_status).encode("utf-8"))
                except Exception:
                    self.close_mqtt()
                    self.last_connect = time.ticks_ms()
                    self.mqtt_status = "Sendefehler"
            self.last_publish = now


async def main():
    """Start Ethernet and HTTP even if the external sensor or MQTT is unavailable."""
    config = load_config()
    lan = setup_lan(config)
    spi = None
    sensor = None
    server = None
    device = None
    try:
        try:
            spi = machine.SPI(1, baudrate=1000000, polarity=0, phase=0,
                              sck=machine.Pin(SENSOR_SCK), miso=machine.Pin(SENSOR_MISO),
                              mosi=machine.Pin(SENSOR_MOSI))
            sensor = MAX31855(spi, machine.Pin(SENSOR_CS, machine.Pin.OUT))
        except (ValueError, OSError):
            print("Sensor nicht initialisiert. SPI-Pins und Verdrahtung pruefen.")
        device = Device(config, lan, sensor)
        web = ConfigServer(config, device.status, device.request_restart)
        server = await asyncio.start_server(web.handle, "0.0.0.0", 80, backlog=2)
        previous_ip = None
        print("HTTP gestartet. Warte auf Ethernet/IP (DHCP standardmaessig aktiv).")
        while True:
            address = lan.ifconfig()[0] if lan.isconnected() else "0.0.0.0"
            if address != previous_ip:
                if address != "0.0.0.0":
                    print("Konfiguration: http://" + address + "/")
                else:
                    print("Kein Ethernet-Link oder keine IP. Kabel und DHCP pruefen.")
                previous_ip = address
            device.step()
            await asyncio.sleep_ms(100)
    finally:
        if server is not None:
            server.close()
            await server.wait_closed()
        if device is not None:
            device.close_mqtt()
        if spi is not None:
            spi.deinit()
        lan.active(False)


if __name__ == "__main__":
    asyncio.run(main())